css:
.cx-stage { height: 430px; border-radius: 8px; }
.nu-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.cx-stage canvas, .nu-stage canvas { touch-action: none; cursor: grab; }
.cx-stage canvas.holding, .nu-stage canvas.holding { cursor: grabbing; }
.nu-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.2em; }
.nu-table { width: 100%; border-collapse: collapse; font-size: 19px; }
.nu-table th, .nu-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: center; }
.nu-table thead th { background: #eef2f7; }
.nu-side { margin: 0; font-size: 18px; color: var(--ink-2); }

